instance.common:
// lib module colormap@1 (design/programmable-graphics.md, Lib Modules): the
// host's colormaps. A piece that imports it calls colormap::sample,
// colormap::viridis or colormap::magma. Released; never changes.

// The rows of caliper_colormaps.
const colormap__VIRIDIS: u32 = 0u;
const colormap__MAGMA: u32 = 1u;
const colormap__RDBU: u32 = 2u;
const colormap__GREYS: u32 = 3u;

// The color of t, from 0 to 1, on a host colormap, linear between its texels.
fn colormap__sample(map: u32, t: f32) -> vec4<f32> {
    let size = textureDimensions(caliper_colormaps);
    let row = i32(min(map, size.y - 1u));
    let x = clamp(t, 0.0, 1.0) * f32(size.x - 1u);
    let x0 = i32(floor(x));
    let x1 = min(x0 + 1, i32(size.x) - 1);
    let a = textureLoad(caliper_colormaps, vec2<i32>(x0, row), 0);
    let b = textureLoad(caliper_colormaps, vec2<i32>(x1, row), 0);
    return mix(a, b, x - f32(x0));
}

fn colormap__viridis(t: f32) -> vec4<f32> {
    return colormap__sample(colormap__VIRIDIS, t);
}

fn colormap__magma(t: f32) -> vec4<f32> {
    return colormap__sample(colormap__MAGMA, t);
}
// The sizes of the model and of its fixed sentence, which both halves read.
const L: u32 = 2u;     // layers
const H: u32 = 4u;     // heads
const T: u32 = 32u;    // tokens of the fixed sentence
const P: u32 = 12u;    // length of the repeated segment
const S: u32 = 4u;     // first token of its first copy

// The grid's place in the panel, in uv from the top left. The margin on the left holds the words
// of the rows; the diagonal names the columns, since row t and column t are the same token.
const GX0: f32 = 0.10;
const GY0: f32 = 0.035;
const GX1: f32 = 0.995;
const GY1: f32 = 0.99;

// The clip-space point of a place in uv from the top left; the piece draws with no camera.
fn clip_of(uv: vec2<f32>) -> vec4<f32> {
    return vec4<f32>(2.0 * uv.x - 1.0, 1.0 - 2.0 * uv.y, 0.0, 1.0);
}

instance.derive:
// Batch row 0 of the (B, H, T, T) weights of each layer, which the script publishes as
// (B * H * T, T) rows, is their first H * T * T values: layer 0's row first, then layer 1's.
@compute @workgroup_size(256)
fn copy_rows(@builtin(global_invocation_id) id: vec3<u32>) {
    let n = H * T * T;
    if (id.x >= n) {
        return;
    }
    pattern[id.x] = attn0[id.x];
    pattern[n + id.x] = attn1[id.x];
}

// One label for each token: its word at the left of its row, beside the grid.
@compute @workgroup_size(32)
fn place_labels(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= T) {
        return;
    }
    let cell_y = (GY1 - GY0) / f32(T);
    // At the left edge, half a row up: the anchor compensates for the label placer's offset.
    labels[id.x] = Label(clip_of(vec2<f32>(0.0, GY0 + (f32(id.x) - 0.5) * cell_y)), id.x);
}

instance.draw:
// Rows are the query token, from the top; columns the key token, from the left.
fn value(layer: u32, head: u32, i: u32, j: u32) -> f32 {
    return pattern[((layer * H + head) * T + i) * T + j];
}

// The attention grid of the head that the params name: one flat cell for each pair of tokens, in
// magma, a thin gap between cells, the empty half where a token would look ahead, an outline on
// the cells that an induction head fills, and the row and column under the pointer lit.
@fragment
fn grid(in: CaliperFullscreen) -> @location(0) vec4<f32> {
    let bg = vec4<f32>(0.094, 0.090, 0.086, 1.0);
    let span = vec2<f32>(GX1 - GX0, GY1 - GY0);
    let c = (in.uv - vec2<f32>(GX0, GY0)) / span * f32(T);
    let px = fwidth(c);   // cells per pixel, before any branch
    if (any(c < vec2<f32>(0.0)) || any(c >= vec2<f32>(f32(T)))) {
        return bg;
    }
    let layer = u32(clamp(params.layer, 0, 1));
    let head = u32(clamp(params.head, 0, i32(H) - 1));
    let j = u32(c.x);
    let i = u32(c.y);
    let f = fract(c);
    if (j > i) {
        return bg;
    }
    let w = value(layer, head, i, j);
    var color = colormap__magma(clamp(w * params.gain, 0.0, 1.0));

    // The row and the column under the pointer.
    let pv = caliper_view.pointer;
    if (pv.w > 0.5) {
        let pc = (pv.xy / caliper_view.viewport.zw - vec2<f32>(GX0, GY0)) / span * f32(T);
        if (all(pc >= vec2<f32>(0.0)) && all(pc < vec2<f32>(f32(T)))) {
            let hover = vec2<u32>(pc);
            if (hover.x == j || hover.y == i) {
                color = mix(color, vec4<f32>(1.0), 0.12);
            }
        }
    }

    // The induction cells: from token t of the second copy to the token after its first occurrence.
    let induction = i >= S + P && i < S + 2u * P && j + P == i + 1u;
    if (induction && (any(f < 2.0 * px) || any(f > vec2<f32>(1.0) - 2.0 * px))) {
        color = vec4<f32>(0.40, 0.82, 0.80, 1.0);
    } else if (any(f < px)) {
        color = mix(color, bg, 0.8);
    }
    return color;
}
